import fs from 'node:fs';
const script = fs.readFileSync(new URL('update-worker.ps1', import.meta.url), 'utf8').replaceAll('\r\n', '\n');
if (script.includes(')FENB"')) throw Error('Invalid updater raw string delimiter');
fs.writeFileSync(new URL('../src/generated/update_worker.hpp', import.meta.url),
  '// Generated by tools/embed-updater.mjs.\n#pragma once\ninline constexpr char UpdateWorker[] = R"FENB(' + script + ')FENB";\n');
